  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    raw_edges = case['distances']

    # Build mutual reachability edges with canonical ordering
    edges = []
    for u, v, d in raw_edges:
        # canonicalize: ensure u <= v (string order works for p0, p1, ...)
        if u > v:
            u, v = v, u
        mutual = max(core_dist[u], core_dist[v], d)
        edges.append((mutual, u, v))

    # Sort by mutual reachability, then by endpoints
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find (Disjoint Set Union)
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == len(nodes) - 1:
                break

    if len(mst_edges) != len(nodes) - 1:
        raise ValueError("Input graph is disconnected; cannot form MST")

    return {"mst_edges": mst_edges, "total_weight": total_weight}
